  "nav.updates.blurb": "Cerca su GitHub un Eldrun più recente e installalo.",
  "updates.help": "Eldrun controlla la pagina delle release GitHub del progetto — solo quando glielo chiedi. Nulla viene scaricato prima di un clic, e il riavvio resta tuo.",
