  "agentCron.title": "Riscaldamento pianificato",
  "agentCron.help":
    "A ogni orario qui sotto Eldrun invia un singolo messaggio «{message}» a quell'agente in background — nella modalità a esecuzione singola della CLI stessa (claude -p, codex exec, …), senza terminale, scheda né progetto. La quota di una CLI agente è una finestra che si apre con il primo messaggio — quella di Claude dura cinque ore — quindi questo decide quando la finestra inizia, invece di lasciarlo al primo prompt vero che digiti.",
  "agentCron.runningNote":
    "Scatta solo mentre Eldrun è in esecuzione. Un orario che passa con l'app chiusa, o con la macchina sospesa, viene saltato per quel giorno e mai inviato in ritardo: inviarlo ore dopo aprirebbe la finestra nel momento peggiore.",
