  "ollama.autostartHelp": "I modelli attivati qui vengono caricati in memoria all'avvio di Eldrun, così tutto ciò che usa un modello locale — completamento automatico, grammatica, una futura valutazione dell'importanza della posta — risponde subito invece di pagare il primo caricamento. Vengono caricati uno dopo l'altro, in questo ordine.",
