  "pill.detachTitle": "{name} — Scollega host SSH",
  "pill.detachDesc1Pre": "Questo trasforma",
  "pill.detachDesc1Mid": "di nuovo in un semplice progetto locale: la sua copia di lavoro locale resta esattamente dov'è e ridiventa la directory del progetto. I file sull'host remoto",
  "pill.detachDesc1Post": "non vengono toccati, e nulla di locale viene eliminato.",
  "pill.detachDesc2Pre": "Ciò che invece viene eliminato è l'",
  "pill.pairingWord": "accoppiamento",
  "pill.detachDesc2Post": ": il lockstep git si ferma, e l'ambito di auto-sincronizzazione scelto per questo host — quali cartelle attraversano, e il registro di ciò che era già in sincronia — viene scartato. Ricollegare lo stesso host in seguito significa scegliere di nuovo quell'ambito da zero.",
  "pill.detaching": "Scollegamento…",
