  "pill.containerSettingsTitle": "{name} — Impostazioni container",
  "pill.containerScopeRestartNote": "Cambiarlo riavvia le schede che attraversano il confine — una shell o uno script in esecuzione viene interrotto. Le schede agente non sono interessate in nessuno dei due casi.",
  "pill.containerScopeLegend": "Cosa gira nel container",
  "pill.containerScopeAll": "Tutto in questo progetto",
  "pill.containerScopeAllHelp": "Schede agente, shell, script ed Esegui/Debug del visualizzatore. Nulla di questo progetto raggiunge il resto della macchina.",
  "pill.containerScopeAgents": "Solo schede agente",
  "pill.containerScopeAgentsHelp": "Shell, script ed Esegui/Debug restano sull'host, con la tua toolchain host — un ambiente .venv, conda o pyenv torna a funzionare, perché il suo interprete vive sull'host e non nell'immagine.",
  "pill.containerScopeAgentsCaveat": "L'agente continua a scrivere nella cartella del progetto, quindi uno script che ha scritto dista un clic su Esegui da tutta la tua macchina. Non può compiere quel passo da solo — nessun file del progetto viene riletto come qualcosa da lanciare — ma leggi ciò che esegui. Per codice che ti aspetti ostile e non solo non revisionato, un container è il livello sbagliato.",
  "pill.containerAppliedNote": "Applicato al prossimo avvio del container (attivazione del progetto o creazione scheda) — un container in esecuzione le cui impostazioni sono cambiate viene sostituito automaticamente.",
