  "pill.vmRebuildConfirm": "Il disco della VM verrà ricreato dall'immagine base. Tutto ciò che è nella VM muore con esso — per un progetto senza mirror, il disco della VM È l'albero di lavoro; sopravvive solo ciò che è stato inviato a un remoto git (o scaricato). Continuare?",
