  "pill.vmEgressOpen": "Aperta (rete completa)",
  "pill.vmEgressProxyCaveat": "La VM raggiunge solo gli host qui sotto tramite il proxy di Eldrun; tutto il resto viene bloccato e registrato. Limite onesto: un agente può comunque inviare dati agli endpoint consentiti (p. es. dentro un prompt) — il proxy restringe il canale, non può chiuderlo. Le modifiche alla modalità si applicano al prossimo avvio.",
  "pill.vmEgressOffNote": "Senza uscita di rete la VM non raggiunge nulla — le schede degli agenti cloud non funzionano; usate un modello locale o puro isolamento build/test.",
