  "pill.pythonInterpMenuTitle": "L'ambiente Python in cui gli script di questo progetto vengono eseguiti e debuggati. Rilevato automaticamente per impostazione predefinita (venv nell'albero, poetry, conda, pyenv); blocca un interprete quando il tuo ambiente si trova dove Eldrun non può dedurlo.",
  "pill.pythonInterpreterEllipsis": "Interprete Python…",
  "pill.autoConnectTitleNonHeadless": "Connette questo progetto da solo all'avvio e quando vi passi. Eldrun non gestisce password in questa modalità, quindi il login (e la VPN, se presente) si apre nel terminale root per autenticarti — poi il progetto si connette da solo.",
  "pill.autoConnectTitleEligible": "Connette questo progetto da solo all'avvio e quando vi passi. Non chiede mai nulla: entra direttamente quando l'host è raggiungibile, e attiva la VPN solo quando non lo è.",
  "pill.autoConnectTitleNotEligible": "Salva prima la password SSH (o usa l'autenticazione a chiave) — la connessione automatica è offerta solo quando la connessione non richiede nulla da te.",
  "pill.autoConnectOnLaunch": "Connessione automatica all'avvio",
  "pill.persistSessionsMenuTitle": "Esegue la shell remota e le schede Python/script di questo progetto all'interno di una sessione tmux sull'host, così un'esecuzione lunga continua attraverso una caduta SSH, la sospensione del laptop o la chiusura di Eldrun — la scheda si ricollega alla riconnessione. Chiudere una scheda termina comunque la sua sessione (con conferma). Le schede agente non sono interessate.",
  "pill.persistentSessionsTmux": "Sessioni persistenti (tmux)",
  "pill.remoteControlMenuTitle":
    "Se le schede agente Claude di questo progetto possono essere monitorate/guidate dall'app o dal web di Claude. Clicca per scorrere: usa l'impostazione globale → forza disattivato → forza attivato.",
