  "pill.remoteControlOn": "Controllo remoto: attivato",
  "pill.remoteMachinesMenuTitle": "Aggiungi e gestisci macchine aggiuntive su cui gira questo progetto. Eseguono lo stesso codice (mantenuto in sincronizzazione unidirezionale) come worker di esperimenti in sola lettura; i loro output restano su ciascuna macchina.",
