  "remoteConnect.saveHintKeptTerminal": "conservata nel portachiavi del tuo sistema operativo — un accesso da terminale non viene visto da Eldrun, quindi non viene salvato nulla di nuovo; disattiva per eliminarla",
  "remoteConnect.saveHintSaved": "salvata nel portachiavi del tuo sistema operativo — disattiva per eliminarla",
