  "remoteConnect.autoConnectVpnWarningPre": "Attenzione: se l'host non è raggiungibile direttamente, la connessione automatica attiva la VPN",
  "remoteConnect.autoConnectVpnWarningStrong": "senza chiedere",
  "remoteConnect.autoConnectVpnWarningPost": "— reindirizzando il traffico di questo computer all'avvio. L'indicatore VPN nell'intestazione mostra quando un tunnel è attivo, e può disattivarlo.",
  "remoteConnect.autoConnectInteractiveTitle": "Connette questo progetto da solo all'avvio e quando vi passi. In questa modalità Eldrun non gestisce alcuna password, quindi l'accesso (e la VPN, se questo progetto ne ha una) si apre nel terminale root perché tu ti autentichi — il progetto si connette da solo non appena sei entrato.",
