  "remoteConnect.killConfirmBtn": "Conferma: termina tutti i job",
  "remoteConnect.killArmTitle": "Disconnessione attiva: termina ogni job tmux in esecuzione su questo host e chiude la connessione. I job vengono terminati solo con questo clic — mai al riavvio di Eldrun.",
  "remoteConnect.killArmBtn": "Disconnetti e termina i job",
  "remoteConnect.forgetPasswordTitle": "Elimina la password salvata di questo host dal portachiavi del tuo sistema operativo. La connessione attuale resta attiva; la prossima connessione richiederà di nuovo la password.",
  "remoteConnect.forgetPasswordBtn": "Dimentica password salvata",
  "carefulHost.title": "Tiene il lavoro in background di Eldrun lontano da questa macchina: il censimento delle dimensioni dei file smette di scansionare l'host da solo, e il monitoraggio diventa più economico e lento. Usalo per un nodo di login o qualsiasi macchina condivisa con altri — non per un nodo di calcolo che tieni per la durata di un job, che è tuo finché lo hai.",
  "carefulHost.label": "Vai piano su questa macchina",
  "carefulHost.hintDefault": "per un nodo di login o una macchina condivisa: salta le scansioni che leggono l'intero filesystem",
  "usage.carefulNote":
    "Host HPC — sono elencate solo le tue sessioni e i tuoi processi. Le regole di utilizzo di un cluster non permettono di raccogliere nomi o comandi di altri utenti, quindi questo report non viene eseguito automaticamente qui.",
  "carefulHost.hintOnByDefault": "attivo per impostazione predefinita per ogni macchina remota — disattivalo se questa è tua",
  "carefulHost.hintNotCareful": "questa macchina è tua: monitoraggio completo, come in locale",
  "remoteConnect.vpnSectionAria": "Tunnel OpenVPN",
  "remoteConnect.sshSectionAria": "Accesso SSH",
  "remoteMachines.title": "{name} — Macchine remote",
  "remoteMachines.introPre": "Ogni macchina raggiunta da questo progetto, in un unico posto — la",
  "remoteMachines.introStrongPrimary": "primaria",
  "remoteMachines.introMid1": "che possiede i suoi file e git, più qualsiasi macchina worker aggiuntiva che esegue il suo",
  "remoteMachines.introStrongSameCode": "stesso codice",
  "remoteMachines.introMid2": ". Connetti o gestisci una qualsiasi di esse qui, oppure aggiungi un nuovo worker qui sotto. Per impostazione predefinita un nuovo worker condivide la cartella del progetto della macchina primaria (nessuna copia, nessun git); spunta",
  "remoteMachines.introStrongSyncCopy": "Sincronizza una copia",
