  "savePassword.titleTerminal": "Un accesso da terminale è qualcosa che Eldrun non vede mai, quindi non salva nulla di nuovo — e non elimina nulla. Qualsiasi password già salvata per questo host resta invariata.",
  "savePassword.saveFailedLabel": "Non salvata:",
  "savePassword.lockedBannerPost": ", quindi una password SSH salvata non può essere letta — questa connessione la richiederà di nuovo, e Eldrun non può dirti se ne è già salvata una.",
