  "settings.agentFenceTitle": "Recinto degli agenti",
  "settings.agentFenceEnabled": "Limita gli agenti locali al loro progetto o box",
  "settings.agentFenceHelp": "Attivo per impostazione predefinita. Gli agenti Linux locali possono leggere e scrivere il proprio progetto; i membri dei box possono accedere anche a tutte le radici dei loro box. Gli altri progetti, ~/.ssh, credenziali di hosting/cloud non correlate (gh, AWS, gcloud) e i socket di portachiavi/desktop restano nascosti. Le schede aperte cambiano al riavvio.",
  "settings.agentFenceLimits": "Solo filesystem: la rete resta condivisa. Gli agenti su host remoti e su macOS/Windows non sono confinati. Il sandbox bubblewrap interno di Claude e i comandi docker non funzionano dentro questo limite esterno.",
  "settings.agentFencePaths": "Percorsi di strumenti/configurazione in sola lettura (uno per riga)",
  "settings.agentFenceReset": "Ripristina predefiniti",
  "settings.agentFencePathsHelp": "Questi percorsi vengono ripristinati nella home altrimenti vuota. Aggiungi credenziali solo se un agente ne ha davvero bisogno; diventeranno leggibili da ogni agente locale confinato.",
  "boxEditor.trustNotice": "Gli agenti del box sono confinati alla cartella del box e alle radici dei membri. Il limite container/VM di un membro continua a non applicarsi alle schede del box ({list}).",
  "pill.agentFenceMenuTitle": "Limita gli agenti locali a questo progetto e a tutti i box a cui appartiene. Fai clic per alternare: impostazione globale → disattivato → attivato. Le schede aperte cambiano al riavvio.",
